from pathlib import Path
import base64,html,json,re
root=Path(__file__).resolve().parent
sections=[]
def add(id,title,body):sections.append((id,title,body))
def fig(name,caption):return f'@@FIG:{name}|{caption}@@'
def steps(*items):return '<ol class="steps">'+''.join('<li>'+x+'</li>' for x in items)+'</ol>'
def table(head,rows):return '<div class="table-scroll"><table><thead><tr>'+''.join('<th>'+x+'</th>' for x in head)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+x+'</td>' for x in row)+'</tr>' for row in rows)+'</tbody></table></div>'
def note(s):return '<aside class="note">'+s+'</aside>'
def flow(labels):return '<div class="flow" role="img" aria-label="'+html.escape(' → '.join(labels))+'">'+''.join('<div>'+s+'</div>' for s in labels)+'</div>'
add('inicio','1. Antes de comenzar', '''<p class="lead">Guía de uso por roles para recorrer la recepción, calidad, laboratorio, mezclas y coordinación de incidencias en el simulador PROCO.</p><div class="tags"><span>SIM-0.2</span><span>Sprints 1–6</span><span>Interfaz en español</span><span>Datos sintéticos</span></div><p>Este manual describe las opciones implementadas sobre la base <code>91688b6</code>. Las capturas son reales y proceden de un entorno didáctico separado del taller; sus nombres <code>MANUAL-…</code> no tienen que aparecer en tu ambiente UAT.</p>'''+note('<b>Alcance:</b> herramienta de simulación. Registrar una decisión no mueve material, no para máquinas, no envía mensajes al proveedor ni registra operaciones en ERP. Las reglas DEMO requieren validación de los responsables de PROCO.')+'''<div class="quick"><a href="#roles">¿Qué hago con mi rol? →</a><a href="#recepcion">Registrar una recepción →</a><a href="#nc">Resolver una no conformidad →</a><a href="#proveedor">Gestionar un rechazo →</a></div><h3>Cómo navegar el manual</h3><p>Usa el índice lateral o el buscador. Haz clic en una captura para ampliarla; pulsa Esc para cerrar. «Imprimir / PDF» abre la impresión del navegador. El archivo HTML incluye sus imágenes: puedes copiarlo y abrirlo sin conexión. El acceso a la aplicación sí requiere que el ambiente esté iniciado.</p>''')
add('acceso','2. Acceso y cambio de usuario', '''<p>En el ambiente UAT preparado, abre <a href="http://localhost:18098/" target="_blank" rel="noopener">http://localhost:18098</a>. La aplicación funciona localmente; la dirección de otro ambiente puede ser distinta.</p>'''+steps('Elige la cuenta en <b>Usuario</b>. Cada cuenta tiene un rol fijo; el selector no cambia los permisos de una sesión ya abierta.','Introduce la contraseña local de demostración: <code>Simulacion123!</code>.','Pulsa <b>Entrar a la simulación →</b>. Comprueba el área y el nombre de usuario en la esquina superior derecha.','Para entregar el proceso a otra área, pulsa <b>Salir</b>, elige la siguiente identidad, vuelve a entrar y selecciona de nuevo el expediente.')+fig('01-acceso','Pantalla de acceso. Las once cuentas representan participantes ficticios.')+note('Una misma persona puede practicar varios roles con cuentas distintas. En el taller, la aceptación corresponde a los responsables reales de las áreas; cambiar de usuario no equivale a su firma. Usa sesiones o ventanas separadas si varios participantes trabajan en paralelo.')+'''<h3>Si no puedes entrar</h3><p>Revisa usuario y contraseña. Si aparece una página de error o no carga la aplicación, consulta <a href="#operacion">Inicio y parada del ambiente</a>. El acceso no se publica en la red de planta por defecto.</p>''')
roles=[('Almacén','almacen','Recibir, contar diferencias, registrar muestras, ejecutar aceptación autorizada, habilitar disponibilidad y atender tareas.','recepcion','No libera técnicamente ni autoriza cantidades comerciales.','WAREHOUSE'),('Calidad','calidad / calidad2','Inspeccionar, retener, emitir concepto documental de diferencias, asumir NC y decidir levantamiento o rechazo.','inspeccion','Solo decide una NC el responsable asignado, distinto del reportante y del autor del dictamen.','QUALITY'),('Laboratorio · técnico','tecnico','Registrar el resultado del ensayo crítico de una muestra.','laboratorio','No aprueba su propio ensayo ni libera.','LAB_TECH'),('Laboratorio · aprobador','aprobador','Liberar técnicamente, emitir dictámenes NC y conceptos de mezcla.','liberacion','No sustituye a Calidad en el rechazo o levantamiento formal de la NC.','LAB_APPROVER'),('Tejeduría','tejeduria','Solicitar mezclas, iniciar un montaje autorizado y atender tareas de su área.','mezclas','No autoriza su solicitud ni decide el cierre del montaje.','PRODUCTION_REQUESTER'),('Producción','produccion','Autorizar/denegar mezclas y decidir cierre o cancelación de montajes.','montajes','No libera lotes ni levanta bloqueos de Calidad.','PRODUCTION_APPROVER'),('GEO','geo','Emitir conceptos, atender contención, consultar seguimiento y crear versiones OLA DEMO.','seguimiento','Una alerta o un OLA no decide el proceso.','GEO'),('Tintorería','tintoreria','Emitir conceptos tintóreos, reportar NC y atender contención cuando corresponda.','mezclas','Un concepto no equivale a autorización final de Producción.','DYEING'),('Abastecimiento','abastecimiento / abastecimiento2','Autorizar cantidad excepcional, documentar gestiones de proveedor y atender tareas Procurement.','diferencias','El cierre comercial requiere otra identidad distinta de quien documentó la disposición.','PROCUREMENT')]
add('roles','3. Qué hace cada rol',table(['Área y cuenta','Responsabilidad','Control principal'],[(f'<b>{n}</b><br><code>{u}</code><small>{code}</small>',f'{a}<br><a href="#{link}">Ver recorrido →</a>',r) for n,u,a,link,r,code in roles])+'''<p>Todas las identidades autenticadas pueden consultar los expedientes sintéticos y el seguimiento. Las acciones de escritura se validan por rol, identidad, estado y versión. No hay pantalla de administración de usuarios ni cuenta SIM_ADMIN disponible en esta versión.</p>'''+note('<b>Cuentas alternas:</b> usa <code>calidad2</code> como responsable si <code>calidad</code> abrió la NC. Usa <code>abastecimiento2</code> para cerrar un caso cuya disposición documentó <code>abastecimiento</code>. No intentes corregir permisos usando otra cuenta sin dejar claro quién representa cada acción.'))
add('navegacion','4. Pantallas y controles comunes',table(['Pestaña','Para qué se usa','Opciones principales'],[('Materiales y NC','Recepción, inspección, laboratorio, liberación, disponibilidad, bloqueos y NC.','Nueva recepción; bandeja de lotes; Solo pendientes de mi área; Actualizar; expediente y trazabilidad.'),('Mezclas por montaje','Solicitar una combinación exacta y recabar conceptos.','Nueva solicitud; filtros por montaje, estado y área; conceptos; decisión de Producción; consulta de vigencia.'),('Montajes y tareas','Iniciar ejecución simulada y coordinar incidencias.','Autorización para iniciar; Mis tareas; estados de tarea; acuse/cierre; cierre del incidente, completar o cancelar; JSON.'),('Seguimiento y OLA','Consultar indicadores, objetivos y alertas internas.','Rango UTC, filtros; indicadores; tiempos por área; páginas de tareas; CSV; versiones OLA por GEO.'),('Recepción y proveedor','Diferencias de cantidades y casos comerciales posteriores al rechazo.','Dos bandejas; nueva diferencia; adopción histórica; filtros; apertura por UUID; decisiones y trazabilidad.')])+'''<h3>Leer un expediente antes de actuar</h3>'''+steps('Confirma lote, OC, referencia, cantidad y estado; dos nombres parecidos pueden ser expedientes distintos.','Lee <b>DECISIÓN PENDIENTE</b>, los impedimentos y el responsable. Un estado técnico no resume todos los controles.','Completa <b>Motivo</b> y <b>Evidencia</b> antes de pulsar una acción. Usa referencias sintéticas claras: <code>UAT-S01-20261113-CALIDAD-01</code>.','Si otra área acaba de actuar, usa <b>Actualizar</b>, <b>Actualizar mezclas</b>, <b>Actualizar montajes y tareas</b> o <b>Actualizar expedientes</b>, según la vista.','Comprueba el estado resultante y la nueva entrada del historial. Conserva el identificador si debes informar una incidencia.')+note('Los campos de motivo/evidencia cambian según la acción. El formulario de NC tiene sus propios campos: rellenar el motivo general del lote no completa el motivo de la NC. No se adjuntan fotografías, PDFs o archivos binarios; «evidencia» es una referencia textual.')+'''<h3>Por qué un botón puede estar deshabilitado</h3><p>Puede faltar motivo/evidencia, muestra, ensayo, concepto o tarea; puede no corresponder a tu rol, haberse cerrado el expediente o existir un comando incierto. Un botón oculto o deshabilitado no siempre indica un error. Revisa primero los requisitos de la fase.</p>''')
add('estados','5. Entender el flujo y los estados',flow(['Almacén<br><b>Recepción</b>','Calidad<br><b>Inspección</b>','Almacén / Calidad<br><b>Muestra</b>','Técnico<br><b>Ensayo</b>','Aprobador Lab<br><b>Liberación</b>','Almacén<br><b>Disponibilidad</b>'])+table(['Control','Estados visibles','Qué significa'],[('Calidad técnica','En verificación → En pruebas → Liberado; también Retenido / Rechazado.','Un ensayo favorable permite continuar, pero no sustituye la aprobación de Laboratorio.'),('Inventario simulado','Cuarentena / Bloqueado / Disponible.','Un lote liberado puede seguir bloqueado. Solo Almacén confirma disponibilidad cuando es elegible.'),('Mezcla','En evaluación / Autorizada / Denegada / Revocada.','La autorización vale para lotes, cantidades, montaje y vigencia concretos.'),('Montaje','En ejecución simulada / Suspendido / Producción simulada completada / Incidente cerrado / Cancelado.','Cerrar un incidente no acredita producción completada. Un suspendido no se reanuda automáticamente.'),('Tarea','Abierta → Acusada → Cerrada.','La misma identidad que acusa debe completar; el destinatario es un área concreta.')])+flow(['Hallazgo / NC','Lote <b>bloqueado</b>','Mezcla autorizada <b>revocada</b>','Montaje iniciado <b>suspendido</b>','Áreas: <b>acuse y acciones</b>','Producción: <b>disposición final</b>'])+note('Una reinspección o un reensayo favorable <b>no levantan bloqueos</b>. Cerrar la NC no reactiva una autorización revocada ni reanuda un montaje suspendido. La evaluación retrospectiva conserva los cierres anteriores.'))
add('recepcion','6. Almacén: registrar recepción', '''<p><b>Entrada:</b> OC existente, lote del proveedor, fecha, kilos y ubicación. <b>Salida:</b> lote en verificación y cuarentena.</p>'''+steps('Entra como <code>almacen</code> y abre <b>Materiales y NC → + Nueva recepción</b>.','Selecciona <b>Orden de compra</b>. La opción muestra referencia y proveedor ficticio.','Informa <b>Lote del proveedor</b>, <b>Fecha de fabricación</b>, <b>Cantidad (kg)</b> y <b>Ubicación</b>. La cantidad debe ser positiva y no superar el saldo de la OC; la fecha no puede ser futura.','Escribe motivo y <b>Evidencia de recepción, empaque y checklist</b>.','Pulsa <b>Registrar en cuarentena</b>. Comprueba el expediente creado y entrégalo a Calidad.')+fig('02-recepcion','Nueva recepción con datos de ejemplo. El formulario no confirma disponibilidad.')+table(['Campo','Ejemplo ficticio','Observación'],[('OC','OC-H-001 / OC-E-001','Determina proveedor, referencia y criterio de ensayo.'),('Lote proveedor','UAT-HILO-01','No repetir el mismo lote dentro de la misma OC.'),('Fecha','2026-01-01','Debe corresponder al dato registrado; no se inventa una fecha futura.'),('Cantidad','10 kg','Hasta tres decimales; unidad de la simulación: kg.'),('Ubicación','CUARENTENA-A','Texto de ubicación simulada, no un movimiento físico.'),('Motivo / evidencia','Recepción ficticia / CHECK-UAT-01','Obligatorios; describir el hecho y su respaldo textual.')])+note('Si hay diferencia entre documento y conteo, usa <a href="#diferencias">Diferencias de recepción</a> antes de crear stock por la cantidad controvertida. La apertura de una diferencia no crea ni reserva inventario.'))
add('inspeccion','7. Calidad: inspeccionar o retener',steps('Entra como <code>calidad</code> y selecciona un lote <b>En verificación</b> o <b>Retenido</b>.','Revisa referencia, fecha, identificación, empaque y trazabilidad según el ejercicio. Registra motivo y evidencia en el formulario de decisión del material.','Si cumple, pulsa <b>Inspección conforme</b>: pasa a <b>En pruebas</b> y abre un ciclo nuevo.','Si existe hallazgo, pulsa <b>Retener por hallazgo</b>: queda <b>Retenido / Bloqueado</b>. El bloqueo debe tratarse formalmente antes de la liberación.','Para una NC formal, utiliza <b>Reportar no conformidad y bloquear</b> y asigna responsable independiente; consulta la sección de NC.')+fig('03-inspeccion','Calidad consulta el expediente y elige inspección conforme o retención.')+note('Una inspección conforme después de una retención limpia la muestra y el resultado actuales para iniciar otro ciclo; los hechos anteriores quedan en auditoría. El inventario sigue bloqueado mientras exista un hold activo. Una etiqueta incompleta se representa con un hallazgo textual: no hay carga de fotografía de etiqueta.'))
add('laboratorio','8. Muestra y ensayo: Almacén / técnico', '''<h3>8.1 Registrar la muestra</h3>'''+steps('Con el lote <b>En pruebas</b> y sin muestra del ciclo, entra como <code>almacen</code> o <code>calidad</code>.','Informa <b>Código de muestra</b>, motivo y evidencia.','Pulsa <b>Registrar muestra</b>. Verifica que el código figure en Muestra / ciclo y entrega al técnico.')+fig('04-muestra','Almacén registra una muestra identificada para el ciclo vigente.')+'''<h3>8.2 Registrar el resultado</h3>'''+steps('Entra como <code>tecnico</code>, selecciona el lote y comprueba código de muestra, nombre del ensayo, unidad y rango.','Introduce el resultado numérico y documenta motivo/evidencia.','Pulsa <b>Registrar ensayo</b>. Un resultado conforme deja el lote en pruebas; fuera del rango deja Retenido/Bloqueado.','Si falla, formaliza la NC y acuerda reevaluación o rechazo. No reemplaces el ensayo ya registrado en el mismo ciclo.')+fig('05-ensayo','Laboratorio técnico: resistencia de hilo. El ejemplo 15 corresponde a un rango DEMO.')+table(['Referencia','Ensayo y unidad','Rango ficticio / ejemplo'],[('HILO-DEMO','Resistencia, cN/tex','10–20 inclusive / 15 conforme; 5 no conforme.'),('ELASTANO-DEMO','Elongación, %','400–600 inclusive / 500 conforme.')])+note('SIM-1 utiliza un ensayo crítico y una muestra por ciclo. Los rangos no son especificaciones productivas aprobadas. Un resultado favorable no autoriza mezcla, no levanta un hold ni confirma disponibilidad.'))
add('liberacion','9. Liberación técnica y disponibilidad', '''<h3>9.1 Aprobar en Laboratorio</h3>'''+steps('Entra como <code>aprobador</code> y revisa el expediente y la evidencia de muestra/ensayo.','Confirma que el ensayo es conforme, que no hay bloqueos activos y que el capturador es otra identidad.','Completa motivo/evidencia y pulsa <b>Aprobar liberación técnica</b>.','Comprueba <b>Liberado / Cuarentena</b>; solicita confirmación posterior de Almacén.')+fig('06-liberacion','Aprobador independiente: acción de liberación técnica.')+'''<h3>9.2 Habilitar disponibilidad</h3>'''+steps('Entra como <code>almacen</code> y selecciona el lote liberado en cuarentena.','Comprueba que no existen bloqueos y registra evidencia de la confirmación simulada.','Pulsa <b>Confirmar disponibilidad</b>. Comprueba <b>Liberado / Disponible</b>.')+fig('07-disponibilidad','Almacén tiene una acción distinta para confirmar disponibilidad.')+note('<b>Entrega de responsabilidad:</b> Laboratorio aprueba la calidad técnica; Almacén confirma disponibilidad. Ninguna de estas acciones autoriza automáticamente mezclar lotes.'))
add('nc','10. No conformidades, bloqueos y reensayo', '''<h3>10.1 Reportar y asignar</h3>'''+steps('Abre el expediente en <b>Materiales y NC</b> y despliega <b>Reportar no conformidad y bloquear</b>.','Elige origen: Documental, Laboratorio, Posterior a liberación (solo con lote liberado) u Otro.','Selecciona un <b>Responsable de Calidad</b> distinto del reportante. Usa <code>calidad2</code> si reporta <code>calidad</code>.','Completa <b>Motivo de la NC</b> y <b>Evidencia de la NC</b>, y pulsa <b>Abrir NC y bloquear</b>. Comprueba UUID, responsable y bloqueo.','Si un hallazgo o ensayo ya dejó un bloqueo sin expediente, formalízalo con este paso; la retención no creó por sí sola una NC.')+'''<p>Abastecimiento no abre NC técnicas; usa su caso comercial después del rechazo. La pantalla puede mostrar opciones comunes, pero el servidor rechaza las acciones no autorizadas.</p><h3>10.2 Emitir dictamen y decidir</h3>'''+steps('Con <code>aprobador</code>, dentro de la NC elige <b>Dictamen técnico</b>: Conforme o No conforme. Completa sus campos y pulsa <b>Registrar dictamen NC</b>.','Con la cuenta de Calidad asignada, revisa que el dictamen esté <b>Vigente</b>. Debe emitirse sobre la versión actual del lote.','Selecciona <b>Disposición</b>, motivo y evidencia propios de la decisión NC. Para levantar usa <b>Levantar bloqueo de esta NC</b>; para rechazo, sigue la sección siguiente.','Si cambió el expediente después del dictamen, solicita otro actualizado. No intentes resolver sobre un dictamen histórico.')+fig('08-nc','La NC tiene motivo, evidencia, responsable, dictámenes y decisión propios.')+'''<h3>10.3 Reensayo favorable después de una retención</h3>'''+flow(['Calidad<br>Reinspección conforme','Almacén<br>Nueva muestra','Técnico<br>Ensayo conforme','Aprobador<br>Dictamen NC vigente','Responsable Calidad<br>Levantar bloqueo','Lab / Almacén<br>Liberar y habilitar'])+steps('Calidad reinspecciona el lote retenido; registra otra muestra para el ciclo nuevo.','El técnico registra el nuevo ensayo. Comprueba que el inventario sigue <b>Bloqueado</b>.','Después del ensayo, el aprobador emite dictamen NC Conforme.','El responsable independiente pulsa <b>Levantar bloqueo NC</b>. Exige muestra y ensayo conformes vigentes.','Si era el último bloqueo, el inventario vuelve a cuarentena. Si quedan otras NC/holds activos, sigue bloqueado.','Laboratorio libera, si corresponde, y Almacén confirma disponibilidad. Consulta el historial para ver el ensayo anterior y el nuevo.')+note('Levantar una NC no elimina sus evidencias ni cierra otras NC. El rechazo es terminal. Un montaje suspendido o mezcla revocada no se reactiva al resolver el material.'))
add('diferencias','11. Diferencias de recepción: Almacén y Abastecimiento', '''<p>Este expediente separa <b>cantidad documentada</b>, <b>observada</b> y <b>aceptada</b>. Ejemplo: el documento indica100kg, se observan90kg y se aceptan90kg; faltan10kg contra el documento, sin inventar stock por ellos.</p>'''+flow(['Almacén<br>Abrir diferencia','Almacén<br>Confirmar conteo','Calidad<br>Concepto si hay hallazgo','Abastecimiento<br>Autorizar cantidad','Almacén<br>Ejecutar aceptación'])+'''<h3>11.1 Registrar y confirmar conteo</h3>'''+steps('Con <code>almacen</code>, abre <b>Recepción y proveedor → Diferencias de recepción → Nueva diferencia de recepción</b>.','Informa OC, lote proveedor, fecha, ubicación, referencia documental y ambas cantidades. Usa el formulario superior <b>Motivo de gestión</b> / <b>Evidencia de gestión</b>.','Marca <b>Hallazgo documental o técnico (requiere Calidad)</b> solo si corresponde. Una diferencia aritmética sola no lo exige.','Pulsa <b>Registrar diferencia</b>. No crea lote ni reserva saldo.','Revisa los hechos y pulsa <b>Confirmar conteo observado</b>. Los datos originales y el conteo quedan conservados.')+fig('09-diferencia','Pre-recepción excepcional: documento y observación se registran por separado.')+'''<h3>11.2 Concepto, autorización y aceptación</h3>'''+steps('Si se marcó hallazgo, <code>calidad</code> elige Concepto de diferencia Favorable/Desfavorable y pulsa <b>Registrar concepto de diferencia</b>. Un desfavorable impide autorizar.','Con <code>abastecimiento</code>, selecciona el expediente y completa <b>Cantidad propuesta a aceptar (kg)</b>. Debe ser ≤ observado y ≤ saldo actual de la OC.','Si queda observado no aceptado, completa <b>Plan del remanente no aceptado</b>. Registra cómo se tratará en la simulación, sin afirmar devolución o segregación física real.','Pulsa <b>Autorizar cantidad propuesta</b>. La cuenta debe ser distinta de quienes reportaron, confirmaron conteo o emitieron el concepto.','Con <code>almacen</code>, registra motivo/evidencia y pulsa <b>Ejecutar aceptación autorizada</b>. La aplicación vuelve a comprobar saldo y usa la cantidad autorizada, no una nueva cantidad escrita al aceptar.','Consulta el resultado y, si se creó lote, pulsa <b>Ver lote aceptado</b>. El lote ingresa a cuarentena y debe completar el ciclo técnico normal.')+fig('10-autorizar-cantidad','Abastecimiento autoriza una propuesta; la autorización no reserva el saldo.')+fig('11-diferencia-resuelta','La diferencia resuelta conserva cantidades y el enlace al lote aceptado.')+table(['Resultado','Interpretación'],[('Observado aceptado','Aceptación positiva de todo lo observado.'),('Aceptación parcial','Aceptación positiva menor que lo observado; el remanente no crea stock.'),('Sin cantidad aceptada','Cantidad aceptada0; no crea lote.'),('Cancelado con motivo','Expediente terminal cancelado explícitamente; no crea lote.')])+'''<h3>Correcciones, saldo y búsqueda</h3><p>Si otra recepción reduce el saldo entre autorizar y aceptar, la aceptación se deniega sin crear lote. Abastecimiento puede usar <b>Revisar autorización comercial</b>; Almacén vuelve a ejecutar con la propuesta revisada. Para corregir hechos originales o concepto inmutable, cancela donde esté permitido y crea otro expediente.</p><p>Almacén puede <b>Cancelar diferencia con motivo</b> solo mientras esté Abierto; Abastecimiento después del conteo o autorización. La bandeja muestra los últimos100; <b>Filtrar expediente por OC, lote o estado</b> filtra lo cargado. Para uno anterior, usa <b>ID de expediente → Abrir por ID</b>.</p>''')
add('mezclas','12. Mezclas: Tejeduría, conceptos y Producción', '''<h3>12.1 Solicitar una combinación</h3>'''+steps('Con <code>tejeduria</code>, abre <b>Mezclas por montaje → Nueva solicitud de mezcla</b>.','Escribe <b>Montaje de destino</b> y <b>Vigencia hasta (hora local)</b>, posterior al momento actual.','Selecciona dos o más lotes distintos, liberados, disponibles y sin bloqueos. Informa kilos positivos por lote, sin superar su cantidad individual.','Usa <b>Agregar lote</b> para más participantes (hasta50) o <b>Quitar lote</b> para retirar filas adicionales.','Completa motivo/evidencia y pulsa <b>Registrar solicitud de mezcla</b>. Comprueba combinación exacta y lista de conceptos requeridos.')+fig('12-mezcla-solicitud','Tejeduría define lotes, kilos, montaje y vigencia de una solicitud.')+'''<h3>12.2 Conceptos de las áreas</h3>'''+steps('Entra con <code>aprobador</code>, <code>geo</code>, <code>calidad</code> y, si corresponde, <code>tintoreria</code>. Selecciona el mismo expediente.','Consulta los lotes con <b>Ver lote…</b>, fechas, regla y los impedimentos. El servidor define qué áreas son obligatorias.','Elige <b>Concepto de mezcla</b>: Favorable o Desfavorable. Documenta motivo/evidencia y pulsa <b>Registrar concepto de mezcla</b>.','Repite por cada área requerida. Cada concepto de área es único e inmutable para esa solicitud: una reevaluación necesita un expediente nuevo.')+fig('13-conceptos','En una combinación con elastano DEMO, Tintorería es obligatoria.')+'''<h3>12.3 Decisión final</h3>'''+steps('Con <code>produccion</code>, revisa todos los conceptos y los impedimentos.','Selecciona <b>Decisión de Producción</b>: Autorizar combinación exacta o Denegar solicitud.','Completa motivo/evidencia y pulsa <b>Confirmar decisión de mezcla</b>. No puede autorizar si falta un concepto, hay uno desfavorable o el material ya no es elegible.','En una autorización, usa <b>Consultar autorización vigente</b> para volver a validar montaje, lotes y vigencia antes de usarla.')+fig('14-aprobar-mezcla','Producción confirma una decisión independiente sobre la combinación.')+note('No hay tolerancias automáticas de30/60d ni predicción de compatibilidad. Una autorización no reserva ni consume inventario: otra incidencia puede revocarla. Denegada y Revocada son decisiones terminales; no se editan los ítems para volverlas favorables.')+'''<p><b>Filtros de bandeja:</b> Filtrar por montaje, Estado de mezcla y Área pendiente. «Actualizar mezclas» obtiene cambios de otros participantes. Si una NC afecta un lote de una autorización, esta queda revocada; resolver la NC no la reactiva.</p>''')
add('montajes','13. Montajes y contención entre áreas', '''<h3>13.1 Iniciar con Tejeduría</h3>'''+steps('Abre <b>Montajes y tareas</b> con <code>tejeduria</code>.','Completa motivo y evidencia de acción de montaje.','En <b>Autorización para iniciar</b>, selecciona la autorización vigente. Solo se ofrecen las utilizables que aún no tienen ejecución.','Pulsa <b>Iniciar montaje simulado</b>. El servidor vuelve a validar lotes, vigencia y versión; comprueba «En ejecución simulada».')+fig('15-iniciar-montaje','Tejeduría inicia un montaje desde una autorización específica.')+'''<h3>13.2 Reportar una NC durante la ejecución</h3>'''+steps('Un participante operativo autorizado abre el lote en Materiales y NC y reporta una NC Posterior a liberación, con responsable de Calidad independiente.','Consulta el lote, la mezcla y el montaje: el lote queda Bloqueado, la autorización Revocada y la ejecución Suspendida.','Se crean tareas por área: Almacén, Calidad, Tejeduría y GEO; Tintorería cuando la regla de la mezcla la requiere. El rechazo posterior agrega coordinación de Abastecimiento.','Cada participante entra con su cuenta y atiende su propia tarea. «Mis tareas» está limitado al rol autenticado; el detalle de ejecución muestra la coordinación completa.')+fig('16-contencion','El montaje suspendido conserva el inicio y muestra las acciones por área.')+'''<h3>13.3 Acusar y completar una tarea</h3>'''+steps('Busca el montaje en <b>Mis tareas</b> o en la lista <b>Ejecuciones</b>. Usa el filtro Estado de tarea: Todos, Abierta, Acusada o Cerrada.','Registra motivo/evidencia de acción de montaje y pulsa <b>Acusar tarea [área]</b>. Esto deja responsable e instante del acuse.','Tras realizar la acción <em>simulada</em>, escribe motivo/evidencia de cierre y pulsa <b>Completar tarea [área]</b>.','Debe completar la misma identidad que acusó. No cierres tareas de otra área. Comprueba ambas evidencias y usa <b>Ver lote y expediente NC</b> para relacionar la causa.')+'''<h3>13.4 Decidir el cierre con Producción</h3>'''+table(['Estado / opción','Resultado y requisitos'],[('En ejecución → Completar producción simulada','Solo con autorización todavía utilizable y todas las tareas cerradas. Registra COMPLETED normal.'),('Suspendido → Cerrar incidente con disposición','Solo después de cerrar todas las tareas; registra CLOSED_WITH_INCIDENT, no producción completada.'),('En ejecución o suspendido → Cancelar con disposición','Cancela con motivo/evidencia y tareas cerradas. No borra historial.'),('Cierre heredado tras incidente','Etiqueta de registros históricos COMPLETED que tuvieron suspensión; se presentan separados de producción normal.')])+fig('20-cierre-incidente','Producción tiene una acción específica para cerrar el incidente.')+note('Una ejecución suspendida no se reanuda. Cada autorización tiene como máximo una ejecución; otro comienzo requiere una nueva mezcla y evaluación. Un incidente detectado después del cierre puede generar tareas retrospectivas sin reabrir ni reescribir el montaje.'))
add('proveedor','14. Rechazo y gestión comercial del proveedor', '''<h3>14.1 Rechazo técnico por Calidad</h3>'''+steps('El aprobador de Laboratorio registra en la NC un dictamen <b>No conforme</b> vigente.','La cuenta de Calidad responsable abre la NC y selecciona <b>Disposición</b>: Rechazar · devolución prevista (RETURN_TO_SUPPLIER) o Rechazar · baja prevista (SCRAP).','Registra motivo y evidencia de decisión NC y pulsa <b>Confirmar rechazo definitivo</b>.','Verifica <b>Rechazado / Bloqueado</b>. Con devolución prevista se abre un caso comercial por NC; SCRAP no abre un caso de devolución.')+fig('17-rechazo','La disposición técnica indica un destino previsto; no ejecuta retorno físico.')+'''<h3>14.2 Seguimiento por Abastecimiento</h3>'''+steps('Con <code>abastecimiento</code>, abre <b>Recepción y proveedor → Casos de proveedor</b> y selecciona el lote/caso.','Completa Motivo de gestión, Evidencia de gestión y <b>Referencia de comunicación simulada</b>. Pulsa <b>Registrar contacto simulado</b>. No se envía correo.','En el paso siguiente elige <b>Respuesta simulada del proveedor</b>: Acepta el reclamo, Disputa el reclamo o Sin respuesta (registro explícito). Pulsa <b>Registrar respuesta simulada</b>.','Elige <b>Orientación comercial simulada</b>: Solicitud ficticia de retorno, Solicitud ficticia de crédito u Otro tratamiento. Completa <b>Tratamiento comercial documentado</b> y pulsa <b>Documentar disposición comercial</b>.','Si hay tareas Procurement enlazadas, usa <b>Abrir ejecución de la tarea</b>. Acusa y completa todas las enlazadas con la cuenta que corresponda. No se fabrica una tarea ni un montaje si el rechazo no afectó una ejecución.')+fig('18-proveedor','El caso comercial mantiene el rechazo técnico y enlaza las tareas de coordinación existentes.')+flow(['Calidad<br><b>Rechazo técnico</b>','Abastecimiento<br><b>Contacto</b>','Abastecimiento<br><b>Respuesta</b>','Abastecimiento<br><b>Disposición</b>','Otra identidad<br><b>Cierre administrativo</b>'])+'''<h3>14.3 Cerrar con otra identidad</h3>'''+steps('Entra como <code>abastecimiento2</code> si la disposición la documentó <code>abastecimiento</code>.','Abre el caso y verifica pasos completos y todas sus tareas Procurement enlazadas cerradas. Las demás tareas del montaje tienen su cierre independiente.','Completa motivo/evidencia y referencia de cierre. Marca <b>Confirmo cierre administrativo sin retorno físico ni ERP</b>.','Pulsa <b>Cerrar caso administrativamente</b>. Comprueba identidad de cierre, estado y ambas confirmaciones físicas/ERP en NO.')+fig('19-cierre-comercial','La segunda identidad confirma un cierre exclusivamente administrativo.')+note('El lote sigue Rechazado/Bloqueado y no recupera saldo de OC. Cerrar una tarea no cierra el caso; cerrar el caso tampoco cierra automáticamente el montaje. Una disputa o falta de respuesta requieren tratamiento documentado, no una respuesta inventada.')+'''<h3>14.4 Adoptar un rechazo histórico</h3><p>Solo para un rechazo RETURN_TO_SUPPLIER anterior que no tenga caso: Abastecimiento pulsa <b>Adoptar rechazo histórico</b>, selecciona el lote y su NC, completa motivo/evidencia y pulsa <b>Vincular caso comercial histórico</b>. No cambia la NC, no reabre el lote y no duplica casos ya existentes. No sirve para SCRAP. Para rechazos nuevos el caso se crea automáticamente.</p>'''+fig('23-historico','Formulario de adopción; no es necesario para rechazos nuevos.'))
add('seguimiento','15. Seguimiento, indicadores, OLA y exportaciones', '''<h3>15.1 Consultar indicadores</h3>'''+steps('Abre <b>Seguimiento y OLA</b>. Ajusta <b>Desde (UTC)</b> y <b>Hasta (UTC, exclusivo)</b>; el rango máximo es366días.','Filtra por Área de seguimiento, Montaje exacto, Estado de ejecución y Estado de tarea si lo necesitas. Pulsa <b>Consultar indicadores</b>.','Lee fecha de consulta, tareas/hitos vencidos, NC abiertas, mezclas revocadas, montajes por resultado y tareas por área/tipo/estado.','Consulta los tiempos de respuesta: n es el número de acuses/cierres observados; media y mediana son segundos corridos desde creación. Las tareas abiertas no cuentan como cierres; N/A significa falta de muestras.','Usa <b>Ver ejecución y evidencias</b> en una tarea para pasar al expediente. Actualiza la consulta para ver cambios posteriores al snapshot.')+fig('21-indicadores','Seguimiento con datos sintéticos: estados, coordinación y tiempos observados.')+table(['Etiqueta OLA','Lectura correcta'],[('Sin OLA configurado','No existe objetivo para ese hito; también puede ocurrir con tareas antiguas.'),('En plazo / Próximo a vencer','Hito pendiente dentro de la ventana definida.'),('Vencido','El objetivo ya pasó y el hito sigue pendiente.'),('Completado en plazo / Completado tarde','El acuse o cierre ya ocurrió; se compara su instante con el objetivo original.')])+'''<p>Acuse y cierre son dos hitos distintos; por eso una tarea puede tener dos alertas. Los OLA corren desde la creación en minutos corridos UTC, no en calendario laboral. Leer una alerta no cambia decisiones.</p><h3>15.2 Configurar versiones DEMO con GEO</h3>'''+steps('Con <code>geo</code>, ve a <b>Reglas OLA DEMO vigentes → Crear nueva versión DEMO</b>.','Selecciona Área OLA y Tipo de tarea OLA (Contención, Evaluación retrospectiva o Coordinación de rechazo).','Configura Minutos para acuse, Minutos para cierre y Ventana próxima. Un objetivo vacío significa sin plazo para ese hito.','Documenta Motivo OLA y Evidencia OLA y pulsa <b>Registrar versión OLA DEMO</b>. La versión anterior no se borra.','La nueva versión aplica solo a tareas futuras; las tareas existentes conservan sus plazos capturados al crearse.')+fig('22-ola','Solo GEO ve el formulario para registrar otra versión OLA DEMO.')+'''<h3>15.3 Exportar lo que realmente ofrece la interfaz</h3>'''+table(['Opción','Qué contiene / cómo usarla'],[('Montajes y tareas → Exportar expediente JSON','Selecciona una ejecución. Descarga su expediente simulado con evidencias y controles relacionados; conservar UUID y fecha.'),('Seguimiento y OLA → Exportar CSV de esta página','Exporta solo la página actual de tareas, con filtros y fecha de consulta. Usa Siguiente página de tareas y exporta las demás si las necesitas.'),('Materiales / mezclas / diferencias / proveedor','No tienen un botón general de exportación propio. Consulta sus historiales y captura evidencia; no esperes que el JSON del montaje sustituya el expediente comercial completo.')])+note('Los datos exportados son de simulación. Los indicadores siguen sus filtros y cohortes: el rango selecciona creación de tarea/mezcla, inicio de ejecución o apertura de NC. Un cero o N/A con filtros restrictivos no demuestra que faltó persistencia.'))
add('auditoria','16. Evidencia, trazabilidad y errores', '''<h3>Conservar evidencia comprensible</h3><p>En el lote, consulta <b>Trazabilidad de decisiones</b> y despliega <b>Identificadores del evento</b>. Mezclas, ejecuciones y expedientes de proveedor tienen sus historiales propios. Revisa actor, momento, motivo, evidencia, transición y correlación; cada acción conserva su registro. No hay opciones para editar o eliminar eventos.</p>'''+table(['Situación','Qué hacer'],[('No aparece el lote esperado','Quita «Solo pendientes de mi área», actualiza y comprueba OC/lote. En diferencias/casos, usa UUID si no está entre los últimos100.'),('Versión desactualizada / conflicto','Otra acción cambió el expediente. Actualiza, revisa el nuevo estado y decide si sigue correspondiendo la acción; no repitas a ciegas.'),('Falta muestra, ensayo, concepto o tarea','Completa el requisito con el rol correcto; sigue la decisión pendiente.'),('Dictamen histórico o no soporta disposición','Solicita dictamen actualizado y coherente con la decisión. No cambies la decisión solo para habilitar el botón.'),('Cantidad supera saldo / observado','Comprueba saldo actual y propuesta. Abastecimiento revisa explícitamente; no modifica la OC para evitar la restricción.'),('Rol no autorizado / identidad no independiente','Entra con el rol responsable y respeta la segregación. Asignar responsable no cambia el rol del usuario.'),('Autorización vencida, revocada o material bloqueado','No iniciar ni completar como producción normal; revisar el expediente. Se necesita una solicitud nueva para otra autorización.'),('Expediente terminal','Rechazos, cancelaciones y cierres no se reabren. Conservar el caso y acordar un nuevo expediente cuando proceda.')])+'''<h3>Una operación quedó «sin confirmar»</h3>'''+steps('Si se pierde la respuesta, la aplicación muestra <b>Comando sin confirmar</b> y bloquea nuevos envíos de esa identidad en esa sesión.','No borres los datos del navegador ni vuelvas a crear el lote/caso para «resolverlo». Conserva la pestaña y la identidad que emitió el comando.','Restablece conexión, vuelve a entrar si hace falta y pulsa <b>Reintentar el mismo comando</b>. Se envían el mismo cuerpo y la misma clave para confirmar sin duplicar.','La sesión conserva el pendiente al recargar la misma pestaña. Una nueva pestaña no debe usarse para eludirlo. Si el almacenamiento de sesión fue eliminado o no se puede leer, solicita revisión técnica del estado y los identificadores antes de actuar.','Si indica «Comando confirmado» y falló la consulta posterior, actualiza las lecturas; no vuelvas a ejecutar la mutación.')+fig('24-reintento','Ejemplo real de respuesta interrumpida en el entorno didáctico; el comando se recuperó con la misma clave.')+note('Si el problema persiste, registra usuario, hora, expediente, versión, clave/correlación y texto del error. No adjuntes contraseñas o cabeceras de autorización.'))
add('practica','17. Ejercicios por escenario S01–S10', '''<p>Antes de practicar, acuerda quién representa cada área y usa lotes diferentes para los escenarios destructivos. Registra resultado observado, responsable y evidencia; el manual no declara estos casos aprobados por PROCO.</p>'''+table(['Caso','Recorrido','Comprobación principal'],[('S01 Recepción conforme','Recepción → inspección → muestra → ensayo → liberación → disponibilidad.','Liberado y Disponible, decisiones separadas.'),('S02 Etiqueta/documento incompleto','Calidad retiene y Almacén formaliza NC con responsable independiente.','Retenido/Bloqueado; sin liberación automática.'),('S03 Cantidad distinta','Diferencia → conteo → concepto si aplica → autorización comercial → aceptación.','Documento, observado y aceptado separados; sin exceder saldo.'),('S04 Ensayo fallido','Técnico registra valor fuera de rango → NC → evaluación.','Hold activo; la NC se formaliza explícitamente.'),('S05 Reensayo favorable','Nuevo ciclo → ensayo conforme → dictamen vigente → levantamiento → liberación.','Resultado favorable por sí solo no desbloquea.'),('S06 Dos lotes liberados','Consultar uso sin autorización específica.','No hay inicio habilitado para ese montaje.'),('S07 Mezcla de fechas/referencias','Solicitud exacta → conceptos requeridos → decisión Producción.','Sin tolerancia industrial implícita por fechas.'),('S08 Riesgo tintóreo','Concepto desfavorable impide autorizar; en otro expediente autorizado, NC de Tintorería revoca.','No confundir concepto obligatorio con detección automática de tono.'),('S09 NC con montaje iniciado','Inicio → NC → suspensión → acuses/cierres por área → cierre incidente.','Incidente cerrado distinto de producción completada.'),('S10 Rechazo / proveedor','Dictamen no conforme → rechazo → caso comercial → tareas Procurement → cierre independiente.','Rechazado/Bloqueado, físico NO y ERP NO.')])+'''<p>El reporte de preparación del taller y su matriz detallada se entregan por separado en el repositorio (<code>docs/UAT-READINESS.md</code>). Sus UUID son del volumen preparado y no de estas capturas.</p>''')
add('operacion','18. Inicio, parada y ayuda local', '''<p>Estos comandos corresponden al ambiente UAT ya preparado <code>proco-uat-91688b6</code>, no al entorno de las capturas.</p><pre><code>cd /Users/Jose_Ayala/Documents/ChatGPT/ProcedurePROCO

# Iniciar conservando datos
DB_PORT=55442 BACKEND_PORT=18097 FRONTEND_PORT=18098 \\
  docker compose -p proco-uat-91688b6 start

# Consultar estado
docker compose -p proco-uat-91688b6 ps

# Detener conservando datos
docker compose -p proco-uat-91688b6 stop</code></pre><p>Abre <a href="http://localhost:18098/" target="_blank" rel="noopener">http://localhost:18098</a>. Espera a que PostgreSQL esté saludable y el backend arranque antes de entrar. No ejecutar <code>down -v</code>: elimina el volumen de datos. Otro taller desde cero necesita nombre/volumen nuevo, sufijo por sesión y puertos libres; usar el mismo SHA en el nombre no crea una base limpia si se repite el proyecto.</p><h3>Glosario</h3>'''+table(['Término','Significado en este manual'],[('OC','Orden de compra sintética; limita kilos registrados. Rechazos no restituyen el saldo.'),('NC','Expediente de no conformidad con responsable, evidencia, dictámenes y decisión.'),('Hold / bloqueo','Restricción activa sobre disponibilidad; requiere decisión formal para levantarse.'),('Dictamen','Opinión técnica de Laboratorio sobre una NC y una versión concreta del lote.'),('Concepto','Evaluación de un área sobre la combinación exacta de una mezcla.'),('Montaje','Identificador de destino y ejecución lógica; no representa conexión con una máquina.'),('OLA DEMO','Objetivo ficticio y versionado para acuse/cierre; no acuerdo operativo aprobado.'),('UUID / versión / correlación','Identificador del expediente, contador de cambios e identificador para relacionar eventos/comandos.')])+'''<p class="fine">Manual v1.0 · 13 de noviembre de 2026 · Base funcional: MaterialReviewFlow, commit91688b6 (Sprints1–6). Capturas de datos ficticios obtenidas en proco-manual-91688b6. Referencias contrastadas: UI React, API y políticas implementadas; requisitos SIM-0.2 y guía UAT. Pendiente de revisión y aceptación funcional por los responsables de PROCO.</p>''')
