def renderfig(m):
 name,caption=m.group(1),m.group(2);p=root/'assets'/f'{name}.png'
 if not p.exists():raise SystemExit('Missing screenshot '+str(p))
 figures.append(name);data=base64.b64encode(p.read_bytes()).decode();num=len(figures)
 return f'<figure><button class="shot" type="button" aria-label="Ampliar figura {num}: {html.escape(caption)}"><img src="data:image/png;base64,{data}" alt="{html.escape(caption)}" loading="eager" width="1440" height="1000"></button><figcaption><b>Figura {num}.</b> {caption} <span class="fine">Clic para ampliar.</span></figcaption></figure>'
