body=re.sub(r'@@FIG:([^|]+)\|([^@]+)@@',renderfig,body)
script='''const search=document.querySelector('#search'),chapters=[...document.querySelectorAll('.chapter')],navLinks=[...document.querySelectorAll('nav a')];const normalize=s=>s.normalize('NFD').replace(/[\\u0300-\\u036f]/g,'').toLowerCase();function filter(){const terms=normalize(search.value.trim()).split(/\\s+/).filter(Boolean);let n=0;chapters.forEach(c=>{const show=terms.every(t=>normalize(c.textContent).includes(t));c.hidden=!show;if(show)n++;});navLinks.forEach(a=>{a.hidden=document.querySelector(a.hash).hidden});document.querySelector('#empty').hidden=n!==0;document.querySelector('#searchStatus').textContent=terms.length?n+' de '+chapters.length+' capítulos':'';}search.addEventListener('input',filter);document.querySelectorAll('a[href^="#"]').forEach(a=>a.addEventListener('click',()=>{if(search.value){search.value='';filter();}document.querySelector('.sidebar').classList.remove('expanded');document.querySelector('#menu').setAttribute('aria-expanded','false')}));document.querySelector('#menu').onclick=()=>{const opened=document.querySelector('.sidebar').classList.toggle('expanded');document.querySelector('#menu').setAttribute('aria-expanded',String(opened))};document.querySelector('#reset').onclick=()=>{search.value='';filter();search.focus()};document.querySelector('#print').onclick=()=>{search.value='';filter();window.print()};const modal=document.querySelector('dialog'),large=modal.querySelector('img');document.querySelectorAll('.shot').forEach(b=>b.onclick=()=>{large.src=b.querySelector('img').src;large.alt=b.querySelector('img').alt;modal.showModal()});modal.querySelector('button').onclick=()=>modal.close();modal.addEventListener('click',e=>{if(e.target===modal)modal.close()});window.addEventListener('scroll',()=>{const max=document.documentElement.scrollHeight-innerHeight;document.querySelector('.progress span').style.width=(max>0?100*scrollY/max:0)+'%';let active=chapters.filter(c=>!c.hidden&&c.getBoundingClientRect().top<140).at(-1);navLinks.forEach(a=>a.classList.toggle('active',active&&a.hash==='#'+active.id))},{passive:true});'''
page='<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="Manual de usuario PROCO SIM-0.2 por roles, con capturas y recorridos de Sprints 1–6."><title>PROCO · Manual de usuario del simulador</title><style>'+css+'</style></head><body><a class="skip" href="#contenido">Saltar al manual</a><aside class="sidebar"><button id="menu" class="menu" aria-expanded="false" aria-controls="indice">Índice</button><div class="brand">PROCO</div><small>Manual de usuario · SIM-0.2</small><label for="search">Buscar en el manual</label><input id="search" type="search" placeholder="Ej.: muestra, rechazo, GEO…" autocomplete="off"><div id="searchStatus" role="status" aria-live="polite"></div><div class="tools"><button id="reset">Limpiar búsqueda</button><button id="print">Imprimir / PDF</button></div><nav id="indice" aria-label="Índice del manual">'+nav+'</nav><small>v1.0 · Solo simulación</small></aside><div class="progress" aria-hidden="true"><span></span></div><main id="contenido"><header class="masthead"><p class="eyebrow">MaterialReviewFlow / Guía práctica multiactor</p><h1>Del material recibido<br>a cada decisión trazable.</h1><p>Cómo usar el simulador PROCO entre Almacén, Calidad, Laboratorio, Producción y las áreas de apoyo.</p><p class="fine">Manual v1.0 · 18 capítulos · Capturas reales · Navegación sin conexión</p><p class="print-note">Copia impresa. La versión HTML permite buscar y ampliar las capturas.</p></header><p id="empty" class="empty" hidden>No hay capítulos con esos términos. Prueba una palabra más breve o limpia la búsqueda.</p>'+body+'<footer>PROCO SIM-0.2 · Manual de simulación · Las decisiones operativas requieren validación de sus responsables.</footer></main><dialog aria-label="Captura ampliada"><button type="button">Cerrar · Esc</button><img alt=""></dialog><script>'+script+'</script></body></html>'
